}

import java.util.Scanner;
public class Main{
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        int num=1;
        for(int i=n;i>=1;i--){
            for(int j=1;j<=i;j++){
                System.out.printf("%4d",num++);
            }
            System.out.println();
        }
    }
}

public class Main{
    public static void main(String[] args){
        for(int i=100;i<=999;i++){
            int ge=i%10;
            int shi=i/10%10;
            int bai=i/100;
            if(ge*ge*ge+shi*shi*shi+bai*bai*bai==i){
                System.out.println(i);
            }
        }
    }
}

import java.util.Scanner;
public class Main{
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        if(n<1||n>9){
            System.out.println("INPUT ERROR.");
            return;
        }
        for(int i=1;i<=n;i++){
            for(int j=1;j<=i;j++){
                if(j>1) System.out.print("\t");
                System.out.print(i+"X"+j+"="+i*j);
            }
            System.out.println();
        }
    }
}

import java.util.Scanner;
public class Main{
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        long oddSum=0,evenSum=0;
        for(int i=1;i<=n;i++){
            if(i%2==1) oddSum+=i;
            else evenSum+=i;
        }
        System.out.println(oddSum);
        System.out.println(evenSum);
    }
}
